export type ClaimSnippet = {
  title: string;
  claim: string;
  scope: string;
  context: string;
  proof: string;
  limit: string;
  supportLabel: string;
  supportHref: string;
};

type TranslationFn = (
  key: string,
  options?: Record<string, unknown>
) => unknown;

const normalizeString = (value: unknown) =>
  typeof value === "string" ? value.trim() : "";

export const normalizeClaimSnippet = (input: unknown): ClaimSnippet | null => {
  if (!input || typeof input !== "object") {
    return null;
  }

  const snippet = input as Partial<ClaimSnippet>;
  const title = normalizeString(snippet.title);
  const claim = normalizeString(snippet.claim);
  const scope = normalizeString(snippet.scope);
  const context = normalizeString(snippet.context);
  const proof = normalizeString(snippet.proof);
  const limit = normalizeString(snippet.limit);
  const supportLabel = normalizeString(snippet.supportLabel);
  const supportHref = normalizeString(snippet.supportHref);

  if (
    !title ||
    !claim ||
    !scope ||
    !context ||
    !proof ||
    !limit ||
    !supportLabel ||
    !supportHref
  ) {
    return null;
  }

  return {
    title,
    claim,
    scope,
    context,
    proof,
    limit,
    supportLabel,
    supportHref,
  };
};

export const getClaimSnippet = (t: TranslationFn, key: string) =>
  normalizeClaimSnippet(
    t(key, {
      returnObjects: true,
      defaultValue: null,
    })
  );
